function add(category, templateId, topic, title, prompt, correct, wrongs, explanation, extra = {}, verification = 'original-reviewed') {
  const id = `extra-prog-${String(questions.length + 1).padStart(4, '0')}`;
  correct = String(correct); wrongs = wrongs.map(String);
  assert.equal(wrongs.length, 3, title);
  assert.equal(new Set([correct, ...wrongs]).size, 4, `${title}: choices must differ`);
  const positions = [0, 1, 2, 3];
  let seed = (Math.floor(questions.length / 4) + 1) * 2654435761 >>> 0;
  const nextRandom = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296; };
  for (let j = 3; j > 0; j--) { const p = Math.floor(nextRandom() * (j + 1)); [positions[j], positions[p]] = [positions[p], positions[j]]; }
  const options = [...wrongs];
  for (let j = 2; j > 0; j--) { const p = Math.floor(nextRandom() * (j + 1)); [options[j], options[p]] = [options[p], options[j]]; }
  options.splice(positions[questions.length % 4], 0, correct);
  const difficulty = extra.difficulty || '보통';
  questions.push({ id, track: 'programming', category, learningTopic: topic, templateId, title, prompt: `자체 제작 연습문제 · ${prompt}`, options, difficulty, sourceId: 'original', kind: 'original', ...extra });
  answers[id] = { correctIndex: options.indexOf(correct), explanation, verification };
  templates.set(templateId, (templates.get(templateId) || 0) + 1);
}
function numeric(category, templateId, topic, title, prompt, value, explanation, suffix = '', extra = {}) {
  const fmt = v => `${Number(v.toFixed(6))}${suffix}`;
  const increment = Number.isInteger(value) ? 1 : 0.5;
  add(category, templateId, topic, title, prompt, fmt(value), [fmt(value + increment), fmt(value + increment * 2), fmt(Math.max(0, value - increment))], explanation, extra, 'computed-verified');
  computed++;
}
function runCode(lang, template, topic, title, code, expected, wrongs, explanation, extra = {}) {
  const command = lang === 'Python' ? python : process.execPath;
  const result = spawnSync(command, [lang === 'Python' ? '-c' : '-e', code], { encoding: 'utf8', timeout: 6000 });
  assert.equal(result.status, 0, `${title}: ${result.stderr}`);
  const actual = result.stdout.trim().replace(/\r?\n/g, ' / ');
  assert.equal(actual, String(expected), `${title}: independent runtime mismatch`);
  add(lang, template, topic, title, `${lang === 'Python' ? 'Python 3' : 'Node.js의 JavaScript'} 코드의 출력은? 여러 줄은 /로 구분하고 문자열의 따옴표는 JSON 출력에 포함된 경우만 표시한다.`, expected, wrongs, `${explanation} 실제 ${lang === 'Python' ? 'Python 3' : 'Node.js'} 실행 결과와 대조했다.`, { code, language: lang, ...extra }, 'computed-verified');
  executed++;
}
